// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 v, uint256 e) public {
        // withdraw(amount) deducts exactly the requested amount from the
        // contract balance, for any amount strictly below the balance.
        // The mutant always sends the full balance, so any positive slack e
        // distinguishes it.  Keep the domain wide; only avoid the revert
        // case (value exceeding balance) and keep slack positive.
        v = bound(v, 1, 1 ether);
        e = bound(e, 1, 1 ether);

        vm.deal(address(c), v + e);
        vm.deal(address(this), 1);

        // owner is the deployer (this test contract), so it may withdraw.
        c.withdraw(v);

        assertTrue(address(c).balance == e, "withdraw must deduct exactly the requested amount");
    }

    receive() external payable {}
}
